// Bounded batch ZIP, protected input and cancellation coverage for Flatten PDF.
const fs=require('node:fs/promises');const path=require('node:path');const assert=require('node:assert/strict');const {chromium}=require(process.env.PDFPILOT_PLAYWRIGHT_MODULE||'playwright');const {PDFDocument}=require('pdf-lib');const {unzipSync}=require('fflate');
const base=process.argv[2]||'http://127.0.0.1:4400';const out=path.resolve(process.argv[3]||'docs/product-completion/qa-flatten-batch-2026-10-04');
(async()=>{await fs.mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const page=await browser.newPage({acceptDownloads:true,viewport:{width:1440,height:1000}});const report={base,errors:[],checks:[]};page.on('pageerror',e=>report.errors.push(e.message));try{await page.goto(base+'/flatten-pdf',{waitUntil:'domcontentloaded'});await page.getByRole('button',{name:/Switch to (dark|light) mode/}).waitFor();const bytes=await fs.readFile('/tmp/pdfpilot-flatten-b/forms-source.pdf');const file={name:'duplicate.pdf',mimeType:'application/pdf',buffer:bytes};await page.locator('input[type=file]').first().setInputFiles([file,file]);await page.getByRole('button',{name:'Flatten PDFs',exact:true}).click();await page.getByRole('button',{name:'Download all as ZIP',exact:true}).waitFor();await page.waitForFunction(()=>document.querySelectorAll('article [role=status]').length===2);const pending=page.waitForEvent('download');await page.getByRole('button',{name:'Download all as ZIP',exact:true}).click();const d=await pending;await d.saveAs(path.join(out,'duplicate-names.zip'));const entries=unzipSync(await fs.readFile(path.join(out,'duplicate-names.zip')));assert.equal(Object.keys(entries).length,2);report.zipEntries=Object.keys(entries);for(const content of Object.values(entries)){const pdf=await PDFDocument.load(content);assert.equal(pdf.getForm().getFields().length,0);assert.equal(pdf.getPageCount(),2);}report.checks.push('Duplicate filenames batch:actual ZIP retains two valid2page flattened PDFs');await page.screenshot({path:path.join(out,'batch-result.png'),fullPage:true});await page.getByRole('button',{name:'Start over',exact:true}).click();
 await page.locator('input[type=file]').first().setInputFiles(Array.from({length:20},(_,i)=>({...file,name:`batch-${i}.pdf`})));await page.getByRole('button',{name:'Flatten PDFs',exact:true}).click();await page.getByRole('button',{name:'Cancel remaining files',exact:true}).click();await page.getByRole('button',{name:'Flatten PDFs',exact:true}).waitFor();const before=await page.locator('article [role=status]').count();await page.waitForTimeout(300);assert.equal(await page.locator('article [role=status]').count(),before,'cancelled generation must not add late results');assert.ok(before<20);report.cancelledReadyCount=before;await page.screenshot({path:path.join(out,'cancelled.png'),fullPage:true});await page.getByRole('button',{name:'Flatten PDFs',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('article [role=status]').length===20,{},{timeout:60000});report.checks.push('Cancel20-document batch:stale results suppressed; retry finishes all20');await page.getByRole('button',{name:'Start over',exact:true}).click();
 await page.locator('input[type=file]').first().setInputFiles('/Users/apple/Documents/Codex/2026-10-01/task/qa-fixtures/alpha-password.pdf');await page.getByRole('button',{name:'Flatten PDF',exact:true}).click();await page.locator('article [role=alert]').waitFor();report.protectedMessage=await page.locator('article [role=alert]').innerText();assert.match(report.protectedMessage,/password|encrypt/i);assert.equal(await page.getByRole('button',{name:'Download PDF',exact:true}).count(),0);report.checks.push('Protected PDF rejected with clear message and no download');await page.screenshot({path:path.join(out,'protected-error.png'),fullPage:true});assert.deepEqual(report.errors,[]);report.status='passed';}catch(e){report.status='failed';report.failure=e.message;report.ui=await page.locator('body').innerText().catch(()=> '');await page.screenshot({path:path.join(out,'failure.png'),fullPage:true}).catch(()=>{});process.exitCode=1;}finally{await fs.writeFile(path.join(out,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1;});
